// src/functions/context.ts
init_schema();
function estimateTokens(text) {
  return Math.ceil(text.length / 3);
}
function escapeXmlAttr(s) {
  return s.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
function registerContextFunction(sdk, kv, tokenBudget) {
  sdk.registerFunction(
    "mem::context",
    async (data) => {
      const budget = data.budget || tokenBudget;
      const blocks = [];
      const [pinnedSlots, profile, lessons] = await Promise.all([
        isSlotsEnabled() ? listPinnedSlots(kv).catch(() => []) : Promise.resolve([]),
        kv.get(KV.profiles, data.project).catch(() => null),
        kv.list(KV.lessons).catch(() => [])
      ]);
      const slotContent = renderPinnedContext(pinnedSlots);
      if (slotContent) {
        blocks.push({
          type: "memory",
          content: slotContent,
          tokens: estimateTokens(slotContent),
          recency: Date.now()
        });
      }
      if (profile) {
        const profileParts = [];
        if (profile.topConcepts.length > 0) {
          profileParts.push(
            `Concepts: ${profile.topConcepts.slice(0, 8).map((c) => c.concept).join(", ")}`
          );
        }
        if (profile.topFiles.length > 0) {
          profileParts.push(
            `Key files: ${profile.topFiles.slice(0, 5).map((f) => f.file).join(", ")}`
          );
        }
        if (profile.conventions.length > 0) {
          profileParts.push(`Conventions: ${profile.conventions.join("; ")}`);
        }
        if (profile.commonErrors.length > 0) {
          profileParts.push(
            `Common errors: ${profile.commonErrors.slice(0, 3).join("; ")}`
          );
        }
        if (profileParts.length > 0) {
          const profileContent = `## Project Profile
${profileParts.join("\n")}`;
          blocks.push({
            type: "memory",
            content: profileContent,
            tokens: estimateTokens(profileContent),
            recency: new Date(profile.updatedAt).getTime()
          });
        }
      }
      const relevantLessons = lessons.filter((l) => !l.deleted && (!l.project || l.project === data.project)).sort((a, b) => {
        const scoreA = (a.project === data.project ? 1.5 : 1) * a.confidence;
        const scoreB = (b.project === data.project ? 1.5 : 1) * b.confidence;
        return scoreB - scoreA;
      }).slice(0, 10);
      if (relevantLessons.length > 0) {
        const items = relevantLessons.map(
          (l) => `- (${l.confidence.toFixed(2)}) ${l.content}${l.context ? ` \u2014 ${l.context}` : ""}`
        ).join("\n");
        const lessonsContent = `## Lessons Learned
${items}`;
        const mostRecent = relevantLessons.reduce((acc, l) => {
          const t = new Date(l.lastReinforcedAt || l.updatedAt).getTime();
          return t > acc ? t : acc;
        }, 0);
        blocks.push({
          type: "memory",
          content: lessonsContent,
          tokens: estimateTokens(lessonsContent),
          recency: mostRecent,
          sourceIds: relevantLessons.map((l) => l.id)
        });
      }
      const allSessions = await kv.list(KV.sessions);
      const sessions = allSessions.filter((s) => s.project === data.project && s.id !== data.sessionId).sort(
        (a, b) => new Date(b.startedAt).getTime() - new Date(a.startedAt).getTime()
      ).slice(0, 10);
      const summariesPerSession = await Promise.all(
        sessions.map(
          (s) => kv.get(KV.summaries, s.id).catch(() => null)
        )
      );
      const sessionsNeedingObs = [];
      for (let i = 0; i < sessions.length; i++) {
        const summary = summariesPerSession[i];
        if (summary) {
          const content = `## ${summary.title}
${summary.narrative}
Decisions: ${summary.keyDecisions.join("; ")}
Files: ${summary.filesModified.join(", ")}`;
          blocks.push({
            type: "summary",
            content,
            tokens: estimateTokens(content),
            recency: new Date(summary.createdAt).getTime()
          });
        } else {
          sessionsNeedingObs.push(i);
        }
      }
      const obsResults = await Promise.all(
        sessionsNeedingObs.map(
          (i) => kv.list(KV.observations(sessions[i].id)).catch(() => [])
        )
      );
      for (let j = 0; j < sessionsNeedingObs.length; j++) {
        const i = sessionsNeedingObs[j];
        const observations = obsResults[j];
        const important = observations.filter(
          (o) => o.title && o.importance >= 5
        );
        if (important.length > 0) {
          const top = important.sort((a, b) => b.importance - a.importance).slice(0, 5);
          const items = top.map((o) => `- [${o.type}] ${o.title}: ${o.narrative}`).join("\n");
          const content = `## Session ${sessions[i].id.slice(0, 8)} (${sessions[i].startedAt})
${items}`;
          blocks.push({
            type: "observation",
            content,
            tokens: estimateTokens(content),
            recency: new Date(sessions[i].startedAt).getTime(),
            sourceIds: top.map((o) => o.id)
          });
        }
      }
      blocks.sort((a, b) => b.recency - a.recency);
      let usedTokens = 0;
      const selected = [];
      const accessedIds = [];
      const header = `<agentmemory-context project="${escapeXmlAttr(data.project)}">`;
      const footer = `</agentmemory-context>`;
      usedTokens += estimateTokens(header) + estimateTokens(footer);
      for (const block of blocks) {
        if (usedTokens + block.tokens > budget) continue;
        selected.push(block.content);
        usedTokens += block.tokens;
        if (block.sourceIds && block.sourceIds.length > 0) {
          accessedIds.push(...block.sourceIds);
        }
      }
      if (accessedIds.length > 0) {
        void recordAccessBatch(kv, accessedIds);
      }
      if (selected.length === 0) {
        logger2.info("No context available", { project: data.project });
        return { context: "", blocks: 0, tokens: 0 };
      }
      const result = `${header}
${selected.join("\n\n")}
${footer}`;
      logger2.info("Context generated", {
        blocks: selected.length,
        tokens: usedTokens
      });
      return { context: result, blocks: selected.length, tokens: usedTokens };
    }
  );
}

