        kv.list(KV.graphNodes).catch(() => []),
        kv.list(KV.graphEdges).catch(() => []),
        kv.list(KV.semantic).catch(() => []),
        kv.list(KV.lessons).catch(() => []),
        kv.list(KV.crystals).catch(() => [])
